let transcriptOrigin=false;
const beforeTranscriptBind=bind,beforeTranscriptRender=render;
function transcriptScreen(){const p=currentPacket();return heading('From conversation to vendor profile.','Paste a call transcript or upload your notes, then review a structured draft.')+`<section class="card transcript-workspace"><div class="card-head"><div><span class="eyebrow">CALL TRANSCRIPT → VENDOR PROFILE</span><h2 style="margin-top:12px">Add the conversation</h2><p>Keep the original transcript alongside the pre-populated profile for review.</p></div><span class="tag">Sample conversion</span></div><div class="transcript-meta"><div><label for="type">Vendor category</label><select id="type">${Object.keys(samples).map(type=>`<option ${type===state.type?'selected':''}>${type}</option>`).join('')}</select></div><div class="transcript-sample"><label>Try a complete example</label><button class="secondary" id="sample-call">Load sample ${state.type.toLowerCase()} call →</button>${p?`<a href="${docPath(p.documents.call)}" download>Download sample transcript ↓</a>`:''}</div></div><label for="transcript">Call transcript</label><textarea id="transcript" class="transcript-input" placeholder="Paste the conversation here. Include speaker names, vendor details, services, and any pricing discussed.">${esc(state.transcript)}</textarea><div class="transcript-tools"><span id="transcript-count">${state.transcript.length.toLocaleString()} characters${state.file?' · '+esc(state.file):''}</span><button class="text-btn" id="clear-transcript">Clear transcript</button></div><div class="drop transcript-drop"><div><b>Or upload a transcript</b><p>TXT or VTT · up to 2 MB · files stay in this browser session.</p></div><input type="file" id="upload" accept=".txt,.vtt" hidden><button class="secondary" id="browse">Choose file ↑</button></div><div class="notice">ⓘ <span>Simulated conversion: the selected vendor’s fictional source packet supplies the draft. The sample call, follow-up email, rate card, website, and portfolio remain available as evidence. Pasted or uploaded text is retained for this session; arbitrary transcript extraction is not connected.</span></div><div class="footer"><small>Next: review the draft, confirm rates, and resolve missing information.</small><button class="primary" id="convert-transcript">Convert transcript to profile →</button></div></section>`}
render=function(){beforeTranscriptRender();if(state.page==='transcript')$('#crumb').textContent='Transcript to profile';if(state.page==='onboard'&&transcriptOrigin){document.querySelectorAll('nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page==='transcript'));$('#crumb').textContent='Transcript to profile / '+(state.step===3?'Vendor record':'Review draft');const banner=document.createElement('div');banner.className='workflow-banner transcript-return';banner.innerHTML=`<div><b>Transcript conversion · ${esc(state.file||'Pasted conversation')}</b><br>Review the pre-populated draft against the sample sources. Supplemental documents fill details absent from the call.</div><button class="secondary" id="return-transcript">← Edit transcript</button>`;$('#app').prepend(banner);$('#return-transcript').onclick=()=>{state.page='transcript';render();window.scrollTo(0,0)}}};
bind=function(){beforeTranscriptBind();document.querySelectorAll('[data-page]').forEach(b=>{const previous=b.onclick;b.onclick=()=>{transcriptOrigin=b.dataset.page==='transcript';if(transcriptOrigin)state.tab='transcript';previous()}});if(state.page!=='transcript')return;const transcriptInput=$('#transcript');transcriptInput.oninput=e=>{state.transcript=e.target.value;state.file='';$('#transcript-count').textContent=`${state.transcript.length.toLocaleString()} characters`};$('#clear-transcript').onclick=()=>{state.transcript='';state.file='';render()};$('#sample-call').onclick=async()=>{try{const p=await loadPacket();state.transcript=p.documents.call.text;state.file=p.documents.call.filename;render();toast('Sample call transcript loaded. Ready to convert.')}catch(e){toast(e.message)}};$('#convert-transcript').onclick=async()=>{if(state.transcript.trim().length<20){toast('Paste or upload a transcript before converting (at least 20 characters).');transcriptInput.focus();return}try{const p=await loadPacket();state.data=Object.fromEntries(Object.entries(p.fields).map(([key,field])=>[key,field.value]));state.data.sourcePacket=`samples/${state.type.toLowerCase()}/packet.json`;state.data.transcriptImport={filename:state.file||'Pasted transcript',characters:state.transcript.length,mode:'Simulated sample conversion with supplemental documents'};sectionIndex=0;aiStarted=null;rateDraft=state.data.price;if(certificate?.url)URL.revokeObjectURL(certificate.url);certificate=null;activeEvidence=null;sourceTab='call';state.page='onboard';state.mode='after';state.step=2;state.tab='transcript';transcriptOrigin=true;render();window.scrollTo(0,0);toast('Transcript draft prepared. Review the pre-populated vendor profile.')}catch(e){toast(e.message)}}};
if(location.hash==='#transcript'){state.page='transcript';state.tab='transcript';transcriptOrigin=true;}render();
